import { Component, input } from '@angular/core';

/** hrm-form-field — bọc 1 control: label + required/optional + error/help. Theme token.
 *  <hrm-form-field label="Họ tên" [required]="true" error="Bắt buộc">
 *    <hrm-input [(ngModel)]="name" />
 *  </hrm-form-field>
 *  optional: đánh dấu trường không bắt buộc; text hiển thị do caller cấp qua optionalLabel
 *  (mặc định '' để giữ i18n-clean — required/optional loại trừ nhau). */
@Component({
  selector: 'hrm-form-field',
  template: `
    @if (label()) {
      <label class="ff-label">
        {{ label() }}
        @if (required()) { <span class="ff-req">*</span> }
        @else if (optional() && optionalLabel()) { <span class="ff-opt">{{ optionalLabel() }}</span> }
      </label>
    }
    <div class="ff-control"><ng-content /></div>
    @if (error()) {
      <div class="ff-error">{{ error() }}</div>
    } @else if (help()) {
      <div class="ff-help">{{ help() }}</div>
    }
  `,
  host: { class: 'hrm-form-field' },
  styles: [`
:host { display: block; margin-bottom: var(--space-4); }
.ff-label { display: block; margin-bottom: var(--space-1-5); font-size: var(--fs-14); font-weight: 500; color: var(--text-strong); }
.ff-req { color: var(--error-base); margin-left: 2px; }
.ff-opt { margin-left: var(--space-1-5); font-size: var(--fs-12); font-weight: 400; color: var(--text-sub); }
.ff-error { margin-top: var(--space-1); font-size: var(--fs-12); color: var(--error-base); }
.ff-help { margin-top: var(--space-1); font-size: var(--fs-12); color: var(--text-sub); }
  `],
})
export class HrmFormField {
  readonly label = input('');
  readonly required = input(false);
  readonly optional = input(false);
  readonly optionalLabel = input('');
  readonly error = input('');
  readonly help = input('');
}
